// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(address nft, uint16 feeRate, uint128 vBase, uint128 vNft, uint56 changeFee) public {
        // Admissible domain: pool pays no royalties / no stolen-nft oracle checks, fee rate must be legal,
        // and the NFT address must be nonzero so it is distinguishable from the native base token.
        vm.assume(nft != address(0));
        feeRate = uint16(bound(feeRate, 0, 5_000));

        c.initialize(
            address(0), // base token is native ETH
            nft,
            vBase,
            vNft,
            changeFee,
            feeRate,
            bytes32(0),
            false,
            false
        );

        // General rule: with baseToken initialized to the native token, the flash-loan fee token
        // is always the native token (address 0). The mutant stores the NFT address in baseToken,
        // so flashFeeToken() returns the nonzero NFT address.
        assertTrue(c.flashFeeToken() == address(0));
    }
}
